// Build the list of exam codes and their URL list paths
const exams = ['ai-102', 'az-104', 'az-305', 'gh-300', 'ab-100', 'ai-103'];
const items = exams.map(code => ({
  json: {
    exam_code: code.toUpperCase(),
    url_file: `/home/node/certmasterai/urls/${code}.txt`,
    scraped_dir: `/home/node/certmasterai/scraped/${code}`
  }
}));
return items;

// Identify which exams have zero chunks and need indexing
const status = $input.first().json;
const stats = status.chroma_db_stats || {};
const needsIndex = Object.entries(stats)
  .filter(([code, count]) => count === 0)
  .map(([code]) => ({ json: { exam_code: code, needs_index: true, current_chunks: 0 } }));
const healthy = Object.entries(stats)
  .filter(([code, count]) => count > 0)
  .map(([code, count]) => ({ json: { exam_code: code, needs_index: false, current_chunks: count } }));
console.log(`Needs indexing: ${needsIndex.map(i => i.json.exam_code).join(', ') || 'none'}`);
console.log(`Healthy: ${healthy.map(i => i.json.exam_code + '(' + i.json.current_chunks + ')').join(', ') || 'none'}`);
return [...needsIndex, ...healthy];
